  "indicator_readings": [
    {
      "indicator": "Close",
      "reading": "36.13 (2025-07-01)",
      "interpretation": "Fechamento levemente abaixo de MM20 (36,197) e MM50 (36,239); acima de EMA9/EMA21."
    },
    {
      "indicator": "MM20",
      "reading": "36.1970",
      "interpretation": "Curto prazo: achatando e cruzou abaixo da MM50 (enfraquecimento da alta)."
    },
    {
      "indicator": "MM50",
      "reading": "36.2390",
      "interpretation": "Média de médio prazo; atua como resistência imediata enquanto preço estiver abaixo."
    },
    {
      "indicator": "MM200",
      "reading": "32.4615",
      "interpretation": "Longo prazo: preço bem acima da MM200 — tendência estrutural ainda positiva."
    },
    {
      "indicator": "EMA9",
      "reading": "35.8786",
      "interpretation": "EMA9 abaixo da EMA21; curto prazo com momentum fraco, mas preço acima da EMA9."
    },
    {
      "indicator": "EMA21",
      "reading": "36.0714",
      "interpretation": "EMA21 ligeiramente abaixo do preço; ponto de referência de curto prazo."
    },
    {
      "indicator": "MACD",
      "reading": "-0.1320 (MACD) / -0.0506 (Signal) / -0.0814 (Hist)",
      "interpretation": "MACD abaixo da linha de sinal e histograma negativo — pressão vendedora no curto/médio prazo."
    },
    {
      "indicator": "RSI14",
      "reading": "50.6200",
      "interpretation": "Neutro — sem condição de sobrecompra ou sobrevenda."
    },
    {
      "indicator": "Bollinger Bands",
      "reading": "BB_lower 35.1409 / BB_mid 36.1970 / BB_upper 37.2531",
      "interpretation": "Preço entre média e banda inferior; bandas com largura moderada, favorecendo movimento lateral/baixa."
    },
    {
      "indicator": "Volume (último pregão)",
      "reading": "22,530,676,100",
      "interpretation": "Volume moderado; recuperação recente não foi confirmada por aumento de volume (inferior a picos de 30/06 e 20/06)."
    }
  ]
}
